/* Shared surfaces for fields and menus.
   .gf = field surface (input, text area, select trigger, combobox)
   .gp = floating panel (select list, dropdown menu, combobox results) */
:root {
  --glass-tint: #2d6cf6;
  --glass-fg: #14161b;
  --glass-on-tint: #ffffff;
  --glass-danger: #d12c3a;
  --glass-radius: 12px;
  --glass-blur: 14px;
  --glass-shadow: 16 20 30;
}

/* ---------- Field wrapper ---------- */
.gfield { display: flex; flex-direction: column; gap: 6px; min-width: 0; text-align: left; }
.gfield-label { font-size: 13px; font-weight: 500; color: var(--glass-fg); }
.gfield-foot { display: flex; justify-content: space-between; gap: 12px; font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.62); }
.gfield[data-invalid] .gfield-hint { color: var(--glass-danger); }

/* ---------- Field surface ---------- */
.gf {
  --gf-h: 40px;
  --gf-fill: #fff;
  --gf-backdrop: none;
  --gf-inset: inset 0 0 0 0 transparent;
  --gf-ring: rgb(var(--glass-shadow) / 0.14);
  --gf-halo: transparent;
  --gf-rim-hi: transparent;
  --gf-rim-lo: transparent;

  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: var(--gf-h);
  padding: 0 12px;
  border: 0;
  border-radius: min(var(--glass-radius), calc(var(--gf-h) / 2));
  font: inherit;
  font-size: 14px;
  text-align: left;
  color: var(--glass-fg);
  background: var(--gf-fill);
  -webkit-backdrop-filter: var(--gf-backdrop);
  backdrop-filter: var(--gf-backdrop);
  box-shadow:
    var(--gf-inset),
    0 0 0 1px var(--gf-ring),
    0 1px 2px rgb(var(--glass-shadow) / 0.05),
    0 0 0 4px var(--gf-halo);
  transition: box-shadow 0.16s ease;
  cursor: text;
}
.gf::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  padding: 0.5px;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(135deg, var(--gf-rim-hi), var(--gf-rim-lo) 38%, var(--gf-rim-lo) 62%, var(--gf-rim-hi));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
}
/* Focus: the edge takes the brand colour and a soft halo grows around it */
.gf:focus-within,
.gf:focus-visible,
.gf[data-open] {
  --gf-ring: var(--glass-focus, var(--glass-tint));
  --gf-halo: color-mix(in srgb, var(--glass-tint) 18%, transparent);
  outline: none;
}
.gfield[data-invalid] .gf {
  --gf-ring: var(--glass-danger);
}
.gfield[data-invalid] .gf:focus-within { --gf-halo: color-mix(in srgb, var(--glass-danger) 16%, transparent); }
.gf[data-multiline] { align-items: flex-start; border-radius: min(var(--glass-radius), 18px); }
.gf:disabled,
.gf[data-disabled] { opacity: 0.5; cursor: not-allowed; }

.gf[data-effect="glass"],
.gf[data-effect="bubble"] {
  --gf-backdrop: blur(var(--glass-blur)) saturate(1.8) brightness(1.06);
  --gf-ring: rgb(var(--glass-shadow) / 0.08);
  --gf-rim-hi: rgb(255 255 255 / 1);
  --gf-rim-lo: rgb(255 255 255 / 0.3);
}
.gf[data-effect="glass"] {
  --gf-fill: linear-gradient(180deg, rgb(255 255 255 / 0.58), rgb(255 255 255 / 0.28));
  --gf-inset: inset 0 1px 0 0 rgb(255 255 255 / 0.9);
}
.gf[data-effect="bubble"] {
  --gf-fill: linear-gradient(180deg, rgb(255 255 255 / 0.92), rgb(255 255 255 / 0.3) 52%, rgb(255 255 255 / 0.45));
  --gf-inset: inset 0 1px 0 0 #fff, inset 0 -8px 12px -7px rgb(var(--glass-shadow) / 0.16);
}

.gf-input {
  flex: 1;
  min-width: 0;
  height: var(--gf-h);
  padding: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  color: inherit;
}
textarea.gf-input { height: auto; min-height: 92px; padding: 10px 0; line-height: 1.5; resize: vertical; }
.gf-input::placeholder,
.gf-placeholder { color: rgb(var(--glass-shadow) / 0.45); }
.gf-input:disabled { cursor: not-allowed; }
.gf-icon,
.gf-suffix,
.gf-chevron { display: inline-flex; flex: none; font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.55); }
.gf svg { width: 18px; height: 18px; flex: none; }
.gf-value { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
button.gf { cursor: pointer; }
.gf-mono { font-family: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: 13px; }
.gf-copy {
  flex: none;
  margin-right: -6px;
  padding: 5px 10px;
  border: 0;
  border-radius: min(var(--glass-radius), 14px);
  font: inherit;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--glass-fg);
  background: rgb(var(--glass-shadow) / 0.07);
  cursor: pointer;
  transition: background 0.15s;
}
.gf-copy:hover { background: rgb(var(--glass-shadow) / 0.12); }
.gf-copy:focus-visible { outline: 2px solid var(--glass-focus, var(--glass-tint)); outline-offset: 1px; }
.gf-chevron { transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gf[data-open] .gf-chevron { transform: rotate(180deg); }
/* Stops phones zooming in when a field is focused */
@media (pointer: coarse) { .gf-input { font-size: 16px; } }

/* ---------- Floating panel ---------- */
.gp-anchor { position: relative; }
.gp-anchor[data-inline] { display: inline-block; }
.gp {
  --gp-fill: #fff;
  position: absolute;
  z-index: 30;
  top: calc(100% + 6px);
  left: 0;
  isolation: isolate;
  min-width: 100%;
  width: max-content;
  max-width: min(320px, 86vw);
  max-height: 264px;
  overflow-y: auto;
  padding: 4px;
  border-radius: 14px;
  text-align: left;
  background: var(--gp-fill);
  box-shadow:
    0 0 0 1px rgb(var(--glass-shadow) / 0.1),
    0 4px 10px -4px rgb(var(--glass-shadow) / 0.1),
    0 16px 36px -14px rgb(var(--glass-shadow) / 0.3);
  transform-origin: top;
  animation: gp-in 0.16s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.gp[data-align="end"] { left: auto; right: 0; }
@keyframes gp-in { from { opacity: 0; transform: translateY(-4px) scale(0.98); } }
.gp[data-effect="glass"],
.gp[data-effect="bubble"] {
  -webkit-backdrop-filter: blur(22px) saturate(1.6);
  backdrop-filter: blur(22px) saturate(1.6);
  --gp-fill: rgb(255 255 255 / 0.66);
  box-shadow:
    inset 0 1px 0 0 rgb(255 255 255 / 0.9),
    0 0 0 1px rgb(var(--glass-shadow) / 0.08),
    0 4px 10px -4px rgb(var(--glass-shadow) / 0.1),
    0 16px 36px -14px rgb(var(--glass-shadow) / 0.3);
}
.gp[data-effect="bubble"] {
  --gp-fill: linear-gradient(180deg, rgb(255 255 255 / 0.92), rgb(255 255 255 / 0.62) 40%, rgb(255 255 255 / 0.7));
  border-radius: 20px;
  padding: 6px;
}
/* One highlight that slides between rows instead of jumping */
.gp-hl {
  position: absolute;
  top: 0;
  left: 4px;
  right: 4px;
  z-index: -1;
  border-radius: 10px;
  pointer-events: none;
  background: rgb(var(--glass-shadow) / 0.07);
  transition: transform 0.18s cubic-bezier(0.2, 0.8, 0.2, 1), height 0.18s, opacity 0.12s;
}
.gp[data-effect="bubble"] .gp-hl { left: 6px; right: 6px; border-radius: 14px; }
.gp-item {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 36px;
  padding: 0 10px;
  border-radius: 10px;
  font-size: 14px;
  white-space: nowrap;
  color: var(--glass-fg);
  cursor: pointer;
}
.gp-item[aria-disabled="true"] { opacity: 0.4; cursor: not-allowed; }
.gp-item[data-danger] { color: var(--glass-danger); }
.gp-item svg { width: 17px; height: 17px; flex: none; }
.gp-icon { display: inline-flex; opacity: 0.7; }
.gp-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.gp-hint { margin-left: 14px; font-size: 12px; color: rgb(var(--glass-shadow) / 0.5); }
.gp-check { display: inline-flex; color: var(--glass-focus, var(--glass-tint)); }
.gp-sep { height: 1px; margin: 4px 6px; background: rgb(var(--glass-shadow) / 0.1); }
.gp-empty { padding: 10px; font-size: 13px; color: rgb(var(--glass-shadow) / 0.6); }

/* ---------- Frost: the Mist theme's default look ----------
   Menus and lists become frosted glass panes with a bright rim, and the
   row highlight is a small glass bead that slides between rows. Fields get
   the same soft glass edge. */
[data-glass-tint="frost"] {
  --glass-focus: #6b7586;
}
[data-glass-tint="frost"] .gp {
  --gp-fill: linear-gradient(180deg, rgb(255 255 255 / 0.9), rgb(243 245 249 / 0.86));
  padding: 6px;
  border-radius: min(var(--glass-radius), 18px);
  -webkit-backdrop-filter: blur(24px) saturate(1.8);
  backdrop-filter: blur(24px) saturate(1.8);
  box-shadow:
    inset 0 1px 0 0 #fff,
    inset 0 0 0 0.5px rgb(255 255 255 / 0.9),
    0 0 0 0.5px rgb(70 82 104 / 0.24),
    0 6px 14px -6px rgb(60 72 98 / 0.16),
    0 26px 50px -18px rgb(60 72 98 / 0.4);
}
[data-glass-tint="frost"] .gp[data-effect="glass"],
[data-glass-tint="frost"] .gp[data-effect="bubble"] {
  --gp-fill: linear-gradient(180deg, rgb(255 255 255 / 0.6), rgb(236 240 246 / 0.42));
}
[data-glass-tint="frost"] .gp[data-effect="bubble"] {
  box-shadow:
    inset 0 1.5px 0 0 #fff,
    inset 0 14px 18px -12px rgb(255 255 255 / 0.95),
    inset 0 -12px 18px -12px rgb(60 72 98 / 0.18),
    0 0 0 0.5px rgb(70 82 104 / 0.24),
    0 26px 50px -18px rgb(60 72 98 / 0.4);
}
[data-glass-tint="frost"] .gp-hl {
  left: 6px;
  right: 6px;
  border-radius: min(var(--glass-radius), 12px);
  background: linear-gradient(180deg, #f6f8fb, #e1e6ee 55%, #eaeef4);
  box-shadow: inset 0 1px 0 #fff, inset 0 -1px 0 rgb(255 255 255 / 0.85), 0 0 0 0.5px rgb(70 82 104 / 0.2), 0 2px 5px -2px rgb(60 72 98 / 0.25);
}
[data-glass-tint="frost"] .gp-item { border-radius: min(var(--glass-radius), 12px); }
[data-glass-tint="frost"] .gp-check { color: #4a5363; }
[data-glass-tint="frost"] .gf:not([data-effect="glass"], [data-effect="bubble"]) {
  --gf-fill: linear-gradient(180deg, #ffffff, #f6f8fb);
  --gf-ring: rgb(70 82 104 / 0.2);
  --gf-inset: inset 0 1px 0 0 #fff, inset 0 -1px 2px 0 rgb(60 72 98 / 0.05);
}
[data-glass-tint="frost"] .gf[data-effect="glass"],
[data-glass-tint="frost"] .gf[data-effect="bubble"] {
  --gf-fill: linear-gradient(180deg, rgb(255 255 255 / 0.62), rgb(240 243 248 / 0.4));
}
[data-glass-tint="frost"] .gf:focus-within,
[data-glass-tint="frost"] .gf:focus-visible,
[data-glass-tint="frost"] .gf[data-open] {
  --gf-ring: rgb(70 82 104 / 0.42);
  --gf-halo: rgb(93 102 117 / 0.12);
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .gf:not([data-effect="flat"]) { --gf-fill: #fff; }
  .gp:not([data-effect="flat"]) { --gp-fill: #fff; }
}
@media (prefers-reduced-transparency: reduce) {
  .gf:not([data-effect="flat"]) { --gf-fill: #fff; }
  .gp:not([data-effect="flat"]) { --gp-fill: #fff; }
}
@media (prefers-reduced-motion: reduce) {
  .gp { animation: none; }
  .gp-hl, .gf-chevron, .gf { transition: none; }
}

/* ---------- Any theme over a dark picture (data-glass-on="dark") ----------
   Text that sits straight on the picture turns white. Parts with their own
   solid or milky surface keep dark text, so nothing goes white on white. */
[data-glass-on="dark"] { --glass-fg: #fff; --glass-shadow: 255 255 255; --glass-danger: #ff8a93; color: var(--glass-fg); }
[data-glass-on="dark"] :is(.gf, .gc, .gp, .gtb, .gbn, .gdl, .gbd, .gtt-tip, .gb:not([data-variant="ghost"])) { --glass-fg: #14161b; --glass-shadow: 16 20 30; --glass-danger: #d12c3a; }
/* Text-only buttons take the colour of whatever they sit on, in every theme */
[data-glass-on="dark"] .gb.gb.gb[data-variant="ghost"] { --gb-fg: var(--glass-fg); }
/* The plain grey badge needs a light chip to show on a dark picture */
[data-glass-on="dark"] .gbd:is([data-tone="neutral"], [data-tone="accent"]):not([data-effect="glass"]):not([data-effect="bubble"]) { --gbd-bg: rgb(255 255 255 / 0.88); }
[data-glass-on="dark"] .gtabs:not([data-variant="subtle"]) .gtab[aria-selected="true"] { color: #14161b; }
/* Mist glass over the picture stays clear, so its text stays white */
[data-glass-tint="frost"] [data-glass-on="dark"] :is(.gf, .gc, .gp):is([data-effect="glass"], [data-effect="bubble"]) { --glass-fg: #fff; --glass-shadow: 255 255 255; }
[data-glass-tint="frost"] [data-glass-on="dark"] .gtabs:not([data-variant="subtle"]):not([data-effect="glass"]):not([data-effect="bubble"]) { background: rgb(255 255 255 / 0.14); box-shadow: inset 0 0 0 0.5px rgb(255 255 255 / 0.2); }

/* ---------- Mist over a dark picture (data-glass-on="dark") ---------- */
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="glass"],
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="bubble"] {
  --gf-fill: linear-gradient(180deg, rgb(255 255 255 / 0.14), rgb(255 255 255 / 0.06));
  --gf-ring: rgb(255 255 255 / 0.24);
  --gf-inset: inset 0 1px 0 0 rgb(255 255 255 / 0.35);
  --gf-halo: rgb(255 255 255 / 0.1);
  color: #fff;
}
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="glass"] .gf-input::placeholder,
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="bubble"] .gf-input::placeholder { color: rgb(255 255 255 / 0.6); }
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="glass"] :is(.gf-placeholder, .gf-icon, .gf-chevron, .gf-suffix),
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="bubble"] :is(.gf-placeholder, .gf-icon, .gf-chevron, .gf-suffix) { color: rgb(255 255 255 / 0.6); }
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="glass"] .gf-input,
[data-glass-tint="frost"] [data-glass-on="dark"] .gf[data-effect="bubble"] .gf-input { color: #fff; }
[data-glass-tint="frost"] [data-glass-on="dark"] .gp[data-effect="glass"],
[data-glass-tint="frost"] [data-glass-on="dark"] .gp[data-effect="bubble"] {
  --gp-fill: linear-gradient(180deg, rgb(70 74 90 / 0.5), rgb(40 42 54 / 0.55));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.3), inset 0 0 0 0.5px rgb(255 255 255 / 0.2), 0 24px 50px -16px rgb(0 0 0 / 0.6);
}
[data-glass-tint="frost"] [data-glass-on="dark"] .gp[data-effect="glass"] :is(.gp-item, .gp-check, .gp-hint),
[data-glass-tint="frost"] [data-glass-on="dark"] .gp[data-effect="bubble"] :is(.gp-item, .gp-check, .gp-hint) { color: #fff; }
[data-glass-tint="frost"] [data-glass-on="dark"] .gp[data-effect="glass"] .gp-hl,
[data-glass-tint="frost"] [data-glass-on="dark"] .gp[data-effect="bubble"] .gp-hl {
  background: linear-gradient(180deg, rgb(255 255 255 / 0.24), rgb(255 255 255 / 0.1));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.4), inset 0 0 0 0.5px rgb(255 255 255 / 0.18);
}

/* ---------- Mist for every part ----------
   Mist is the starting look, so it needs no theme file. These rules give the
   newer families (extras, tactile, glance, kit and the AI parts) the same
   frosted glass as the core parts: see-through paper with a bright top edge,
   glossy colour on main buttons, and rounder cards. They step aside wherever
   a data-glass-theme is set. */
:root :is(.ggl:not([data-fill]), .gxw, .gxs-item, .gxm-field, .gxm-list, .gxc-menu, .gxo-panel, .gxd, .gxa, .gcp, .gft, .gptr, .ghh, .gkc, .gst-item, .gam-err, .gam-hist, .gam-men, .gam-art, .gam-diff, .gam-vp-row, .gam-ap, .gdk-card, .gct-body, .gfb, .gapl, .gss):not([data-glass-theme] *):not([data-glass-theme]) { background: linear-gradient(180deg, rgb(255 255 255 / 0.94), rgb(255 255 255 / 0.74)); -webkit-backdrop-filter: blur(20px) saturate(1.5); backdrop-filter: blur(20px) saturate(1.5);
  box-shadow: inset 0 1px 0 #fff, inset 0 0 0 1px rgb(255 255 255 / 0.55), 0 0 0 1px rgb(var(--glass-shadow, 20 24 40) / 0.08), 0 2px 4px rgb(20 30 60 / 0.04), 0 22px 44px -26px rgb(20 30 60 / 0.42); }
:root[data-glass-mode="dark"] :is(.ggl:not([data-fill]), .gxw, .gxs-item, .gxm-field, .gxm-list, .gxc-menu, .gxo-panel, .gxd, .gxa, .gcp, .gft, .gptr, .ghh, .gkc, .gst-item, .gam-err, .gam-hist, .gam-men, .gam-art, .gam-diff, .gam-vp-row, .gam-ap, .gdk-card, .gct-body, .gfb, .gapl, .gss):not([data-glass-theme] *):not([data-glass-theme]) { background: linear-gradient(180deg, rgb(52 52 60 / 0.74), rgb(30 30 36 / 0.66));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.14), 0 0 0 1px rgb(255 255 255 / 0.08), 0 0 0 1px rgb(0 0 0 / 0.4), 0 24px 48px -24px rgb(0 0 0 / 0.9); }
:root :is(.ggl, .gxw, .gcp, .gft, .gptr, .ghh, .gkc, .gam-hist, .gam-men, .gam-art, .gam-diff, .gam-ap, .gxd, .gxa, .gdk-card, .gapl):not([data-glass-theme] *):not([data-glass-theme]) { border-radius: 22px; }
:root :is(.gap-run, .gx-btn-main, .gxb-main, .gxo-btn, .gxa-main, .gam-solid, .gam-men-send, .gam-ap-play, .gam-hist-new, .gkc-send:not([data-stop]), .gn-btn-main, .gn-send, .gn-aw-fab):not([data-glass-theme] *):not([data-glass-theme]) { color: var(--glass-on-tint, #fff); background: linear-gradient(180deg, color-mix(in srgb, var(--glass-tint) 72%, #fff), var(--glass-tint));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.42), inset 0 -1px 0 rgb(0 0 0 / 0.12), 0 0 0 1px color-mix(in srgb, var(--glass-tint) 75%, #000), 0 8px 18px -8px color-mix(in srgb, var(--glass-tint) 70%, transparent); }
:root [data-glass-tint="frost"] :is(.gap-run, .gx-btn-main, .gxb-main, .gxo-btn, .gxa-main, .gam-solid, .gam-men-send, .gam-ap-play, .gam-hist-new, .gkc-send:not([data-stop]), .gn-btn-main, .gn-send, .gn-aw-fab):not([data-glass-theme] *):not([data-glass-theme]), :root [data-glass-tint="frost"]:is(.gap-run, .gx-btn-main, .gxb-main, .gxo-btn, .gxa-main, .gam-solid, .gam-men-send, .gam-ap-play, .gam-hist-new, .gkc-send:not([data-stop]), .gn-btn-main, .gn-send, .gn-aw-fab):not([data-glass-theme] *):not([data-glass-theme]) { color: #1b2230; background: linear-gradient(180deg, #ffffff, #dfe5ee); box-shadow: inset 0 1px 0 #fff, 0 0 0 1px rgb(20 30 50 / 0.14), 0 8px 18px -10px rgb(20 30 60 / 0.45); }
:root[data-glass-mode="dark"] [data-glass-tint="frost"] :is(.gap-run, .gx-btn-main, .gxb-main, .gxo-btn, .gxa-main, .gam-solid, .gam-men-send, .gam-ap-play, .gam-hist-new, .gkc-send:not([data-stop]), .gn-btn-main, .gn-send, .gn-aw-fab):not([data-glass-theme] *):not([data-glass-theme]) { color: #f1f4f8; background: linear-gradient(180deg, #4a505c, #363b45); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.18), 0 0 0 1px rgb(0 0 0 / 0.5), 0 8px 18px -8px rgb(0 0 0 / 0.8); }
